#include <iostream>
#include <set>
using namespace std;

int main() {   //@ @layout open:container
    set<int> s;   //@ @tts [next] 準備一個空的 set
    s.insert(5);   //@ @guide {s} @tts [next] 放進五 @layout bst:s
    s.insert(3);   //@ @guide {s} @tts [next] 放進三
    s.insert(8);   //@ @guide {s} @tts [next] 放進八
    s.insert(1);   //@ @guide {s} @tts [next] 放進一
    s.insert(4);   //@ @guide {s} @tts [next] 放進四
    cout << s.size() << endl;   //@ @guide {s} @tts [next] 一共五個數字
    return 0;   //@ @tts [continue] 程式結束
}
